
function showReward(n){const dialog=$('#reward');dialog.close();dialog.classList.toggle('perfect',n===3);$('#reward-title').textContent=['Encore un essai !','Une première étoile !','Bien joué !','Forme reconnue !'][n];
$('#reward-message').textContent=['Compare les faces et les couleurs. Tu peux reprendre ton dessin.','La forme se dessine ! Affine-la pour gagner la deuxième étoile.','Niveau validé ! Quelques détails te séparent des trois étoiles.','Correspondance visuelle exacte : 100 %.'][n];
$('#reward-stars').replaceChildren();for(let i=0;i<3;i++){const star=document.createElement('span');star.className='reward-star'+(i<n?' won':'');star.textContent=i<n?'★':'☆';star.style.setProperty('--delay',(180+i*280)+'ms');star.setAttribute('aria-hidden','true');$('#reward-stars').append(star)}$('#reward-stars').setAttribute('aria-label',n+' étoiles sur trois');$('#reward-next').hidden=n<2;$('#reward-next').textContent=levelIndex===levels.length-1?'Rejouer depuis le début':'Niveau suivant';$('#reward-retry').textContent=n===3?'Admirer mon dessin':n<2?'Améliorer mon dessin':'Viser les trois étoiles';dialog.showModal()}$('#reward-retry').onclick=()=>$('#reward').close();$('#reward-next').onclick=()=>{$('#reward').close();loadLevel((levelIndex+1)%levels.length)};

function renderPreview(el,bs){const r=el.getBoundingClientRect(),mw=r.width||250,mh=r.height||170,d=window.devicePixelRatio||1;el.width=mw*d;el.height=mh*d;const mc=el.getContext('2d');mc.setTransform(d,0,0,d,0,0);mc.clearRect(0,0,mw,mh);const ff=ordered(bs).flatMap(geometry),pts=ff.flatMap(f=>f.points),minx=Math.min(...pts.map(p=>p.x)),maxx=Math.max(...pts.map(p=>p.x)),miny=Math.min(...pts.map(p=>p.y)),maxy=Math.max(...pts.map(p=>p.y)),s=Math.min((mw-24)/(maxx-minx),(mh-22)/((maxy-miny)*.5));for(const f of ff){mc.beginPath();f.points.forEach((p,i)=>{const x=mw/2+(p.x-(minx+maxx)/2)*s,y=mh/2+(p.y-(miny+maxy)/2)*s*.5;i?mc.lineTo(x,y):mc.moveTo(x,y)});mc.closePath();mc.fillStyle=f.fill;mc.fill();mc.strokeStyle='#20233422';mc.stroke()}}
const previews=[];levels.forEach((l,i)=>{const card=document.createElement('button');card.className='level-card';card.dataset.level=i;const num=document.createElement('span'),preview=document.createElement('canvas'),title=document.createElement('strong'),stars=document.createElement('span');num.className='card-number';num.textContent=`${String(i+1).padStart(2,'0')} · ${l.difficulty}`;title.textContent=l.title;stars.className='card-stars';stars.textContent='À découvrir';preview.setAttribute('aria-hidden','true');card.append(num,preview,title,stars);card.onclick=()=>{if(run)return;loadLevel(i);window.location.hash='';};$('#level-cards').append(card);previews.push(preview)});function galleryRoute(){const open=window.location.hash==='#levels'&&!run;$('#gallery').hidden=!open;$('main').hidden=open;if(open){updateLevelButtons();previews.forEach((el,i)=>renderPreview(el,levels[i].blocks));window.scrollTo(0,0)}else if(game)drawModel()}$('#level-picker').onclick=()=>{if(!run)window.location.hash='levels'};$('#gallery-back').onclick=()=>window.location.hash='';window.addEventListener('hashchange',galleryRoute);window.addEventListener('resize',()=>{if(!$('#gallery').hidden)previews.forEach((el,i)=>renderPreview(el,levels[i].blocks))});galleryRoute();
